import{_ as a,C as s,o as n,c as i,a2 as t,E as r}from"./chunks/framework.9yf7n3zg.js";const d="/guide/media/getting-started-welcome.webp",h="/guide/media/getting-started-first-run-stories.webp",l="/guide/media/getting-started-sample-library.webp",b=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1792171429000}'),g={name:"guide/getting-started.md"};function c(p,e,u,f,m,y){const o=s("Clip");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>This page takes you from the download to your first ten minutes in Leathercase. It covers installing the app on macOS, Windows and Linux, the first-run screens that pick your writing home, the sample library you can try before pointing Leathercase at your own files, and the settings that switch things off.</p><p>Leathercase reads your files where they already are. It never edits your manuscript: everything it adds is its own small files, in markdown and JSON, in a folder you choose.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>Every version is published on the releases page: <a href="https://github.com/Leathercase/leathercase-releases/releases" target="_blank" rel="noreferrer">github.com/Leathercase/leathercase-releases/releases</a>. Open the newest release and download the file for your system from its list of assets.</p><table tabindex="0"><thead><tr><th>System</th><th>File to download</th><th>Updates itself</th></tr></thead><tbody><tr><td>macOS, Apple silicon (M1 and later)</td><td><code>leathercase-&lt;version&gt;-mac-arm64.dmg</code></td><td>Yes</td></tr><tr><td>macOS, Intel</td><td><code>leathercase-&lt;version&gt;-mac-x64.dmg</code></td><td>Yes</td></tr><tr><td>Windows (x64 and Arm)</td><td><code>leathercase-&lt;version&gt;-win.exe</code></td><td>Yes</td></tr><tr><td>Linux, AppImage</td><td><code>leathercase-&lt;version&gt;-linux-x86_64.AppImage</code>, or the <code>arm64</code> one</td><td>Yes</td></tr><tr><td>Linux, Debian and Ubuntu package</td><td><code>leathercase-&lt;version&gt;-linux-amd64.deb</code>, or the <code>arm64</code> one</td><td>No: Leathercase opens the download page instead</td></tr></tbody></table><p>The <code>.zip</code> files beside the macOS installers and the <code>latest*.yml</code> files are for the updater. You do not need them. The <code>SHA256SUMS</code> files let you check a download if you want to.</p><p>&quot;Updates itself&quot; means that when you ask Leathercase to check for a newer version, it can download it and install it on restart. Nothing is checked or downloaded unless you ask. See <a href="/guide/reference/updates">Updates and uninstalling</a>.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><ol><li>Open the <code>.dmg</code> you downloaded.</li><li>In the window that opens, drag <strong>Leathercase</strong> onto <strong>Applications</strong>, following the arrow.</li><li>Open it from Applications or Launchpad.</li></ol><p>The Mac app is signed and notarised by Apple, so it opens without a warning. It needs macOS 12 or later.</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>Run <code>leathercase-&lt;version&gt;-win.exe</code>.</li><li>Windows SmartScreen may warn that the publisher is unknown: the Windows installer is not signed yet. Choose <strong>More info</strong>, then <strong>Run anyway</strong>.</li><li>There is nothing to choose: a small window shows the install&#39;s progress, then Leathercase opens. It installs for you alone, needs no administrator rights, and adds Leathercase to the Start menu and the desktop.</li></ol><h3 id="linux-appimage" tabindex="-1">Linux: AppImage <a class="header-anchor" href="#linux-appimage" aria-label="Permalink to &quot;Linux: AppImage&quot;">​</a></h3><ol><li>Make the file executable: right-click it, open <strong>Properties</strong>, and tick <strong>Allow executing file as program</strong>, or run <code>chmod +x leathercase-*.AppImage</code> in a terminal.</li><li>Double-click it to run.</li></ol><p>The AppImage is the Linux build that can update itself.</p><h3 id="linux-deb" tabindex="-1">Linux: .deb <a class="header-anchor" href="#linux-deb" aria-label="Permalink to &quot;Linux: .deb&quot;">​</a></h3><ol><li>Install it with your software centre, or with <code>sudo apt install ./leathercase-&lt;version&gt;-linux-amd64.deb</code>.</li><li>Open <strong>Leathercase</strong> from your applications menu.</li></ol><p>A <code>.deb</code> cannot replace itself. When a newer version is out, Leathercase opens its download page and you install the new <code>.deb</code> the same way.</p><h3 id="from-a-version-before-0-30" tabindex="-1">From a version before 0.30 <a class="header-anchor" href="#from-a-version-before-0-30" aria-label="Permalink to &quot;From a version before 0.30&quot;">​</a></h3><p>Before 0.30 the app had another name. On Windows and Linux it updates to 0.30 in place, as any update does. On macOS, download 0.30 once by hand and drag it into Applications, then move the old app to the Trash: the app&#39;s identity changed with its name, so the old app cannot replace itself with the new one. Later versions update themselves again. On every system your homes and settings carry over: Leathercase moves them to its own folder the first time it opens.</p><h2 id="the-first-run" tabindex="-1">The first run <a class="header-anchor" href="#the-first-run" aria-label="Permalink to &quot;The first run&quot;">​</a></h2><p>The first time Leathercase opens it has no writing home yet, so it shows the first-run screens instead of the usual window. Nothing is written to your disk until the last step.</p><p><img src="'+d+'" alt="The welcome screen of first run, with the two ways in and the link to the sample" width="810" height="545" loading="lazy"></p><h3 id="welcome" tabindex="-1">Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to &quot;Welcome&quot;">​</a></h3><p>The welcome screen offers two ways in. Click one to choose it; it turns vermilion.</p><table tabindex="0"><thead><tr><th>Card</th><th>Title</th><th>What it does</th></tr></thead><tbody><tr><td><strong>I have a draft</strong></td><td><strong>Read my manuscript</strong></td><td>For a story you have already written. The card says: <strong>From an Obsidian vault, a markdown folder, Scrivener, Word or Fountain. Your files are read, never changed.</strong></td></tr><tr><td><strong>I&#39;m starting out</strong></td><td><strong>Start from ideas</strong></td><td>For a story that does not exist yet. The card says: <strong>Begin with a story of its own. The grid and threads grow as you add to it.</strong></td></tr></tbody></table><p>Press <strong>Continue</strong> to go on with the card you chose, or click <strong>Try the sample story first</strong> to skip all of this and open the sample library (see below). The line at the foot says the promise plainly: nothing leaves this computer.</p><p>The app speaks the language of your system, matched to the nearest of the three it carries (English, Brazilian Portuguese, European Portuguese). First run does not ask. You can pick another language later in <strong>Settings</strong>, <strong>Appearance</strong>; see <a href="/guide/reference/languages">Languages</a>.</p><h3 id="step-1-home" tabindex="-1">Step 1: Home <a class="header-anchor" href="#step-1-home" aria-label="Permalink to &quot;Step 1: Home&quot;">​</a></h3><p>The steps are numbered across the top: <strong>1 Home</strong>, <strong>2 Stories</strong>, <strong>3 Open in</strong> for a draft, or <strong>1 Home</strong>, <strong>2 First story</strong> when you start from ideas.</p><p><strong>Where do you keep your stories?</strong> Your writing home is one folder that holds your stories. Leathercase keeps its own files there too, so whatever syncs that folder (Dropbox, Google Drive, iCloud Drive, OneDrive) carries both.</p><ol><li>Press <strong>Choose…</strong> and pick the folder in your system&#39;s dialog. The box shows <strong>Reading the folder…</strong>, then the folder&#39;s path.</li><li>Under it, Leathercase says what it found: <ul><li>Who carries the folder: <strong>A local folder; no sync tool holds it</strong>, or <strong>Dropbox syncs this folder</strong> with a <strong>detected</strong> badge. Leathercase reads this from the folder&#39;s path only. It never uploads anything itself.</li><li>What is in it: <strong>2 stories found</strong>, <strong>No story found yet</strong>, or <strong>Already a writing home: 3 stories</strong> when you pick a folder Leathercase has used before, on this or another computer. When stories are found, the line under the count says what counts as one: <strong>Folders of markdown, vaults, Word and Fountain files, and Scrivener projects.</strong></li></ul></li><li><strong>Wondering how Leathercase will read your folder? The shape of a story folder</strong> opens a short guide page, with <strong>Back</strong> to return and <strong>Try the sample</strong> to open the sample instead.</li><li><strong>What will be added</strong> lists exactly what Leathercase will write: <ul><li><strong>+ Suite.md</strong>: marks this folder as a writing home.</li><li><strong>+ suite/</strong>: the home&#39;s own files.</li><li><strong>+ Writer/</strong>: your library of references and ideas, made only when you make a card.</li><li><strong>+ one suite/ folder per story</strong>: its settings, grid, threads and graph.</li></ul></li><li>Press <strong>Use this folder</strong>. If the folder is already a writing home and you came by <strong>I have a draft</strong>, the button reads <strong>Open this home</strong> and opens it straight away with its stories as they were left.</li></ol><p>Some folders cannot be a home, and Leathercase says why in rose under the box: the root of a drive, your whole home folder, a system folder, or the folder where Leathercase keeps its own data. Choose the folder inside that holds your stories.</p>',35)),r(o,{name:"getting-started-first-run-home",caption:"Choosing a folder on the Home step: the folder is read, the findings appear, and the list of what will be added"}),e[1]||(e[1]=t('<h3 id="step-2-stories-i-have-a-draft" tabindex="-1">Step 2: Stories (I have a draft) <a class="header-anchor" href="#step-2-stories-i-have-a-draft" aria-label="Permalink to &quot;Step 2: Stories (I have a draft)&quot;">​</a></h3><p><strong>These look like stories</strong> lists every story Leathercase found in the folder: folders of markdown, vaults, Word files, Scrivener projects and Fountain screenplays. Each row shows a tick box, the story&#39;s name, its folder (or <strong>this folder</strong> for the home itself), its source (<strong>Markdown</strong>, <strong>Obsidian</strong>, <strong>Word</strong>, <strong>Scrivener</strong>, <strong>Fountain</strong>) and how many files it has.</p><p>Untick anything that is not a story. Each ticked story gets its own <code>suite/</code> folder. A few are offered unticked, with the reason under the list:</p><ul><li>A folder that holds a single Word file: tick it to read it as a story.</li><li>Files at the top of the folder, beside story folders: tick them to read them as a story of their own.</li></ul><p>The line beside the button counts what you ticked, for example <strong>3 stories · read-only</strong>. Press <strong>Continue</strong>.</p><p><img src="'+h+'" alt="The Stories step of first run, listing the stories found in the sample library folder with their sources" width="905" height="795" loading="lazy"></p><p>When nothing was found, the step says <strong>No stories here yet</strong> and offers <strong>Start from ideas</strong> instead.</p><h3 id="step-3-open-in-i-have-a-draft" tabindex="-1">Step 3: Open in (I have a draft) <a class="header-anchor" href="#step-3-open-in-i-have-a-draft" aria-label="Permalink to &quot;Step 3: Open in (I have a draft)&quot;">​</a></h3><p><strong>Where do you write each story?</strong> When you select a passage in Leathercase, <strong>Open in</strong> takes you back to the app you write in, at that spot. This step picks that app for each story.</p><ul><li>A dashed grey dot means Leathercase inferred the app, and says why: <strong>Inferred from the vault</strong> (Obsidian), <strong>Inferred from .scriv</strong> (Scrivener), or <strong>The only app here that opens .md</strong>.</li><li>An amber dot means several apps on this computer open that format, for example <strong>3 apps open .md files. Pick one.</strong> Choose one from the menu.</li><li><strong>Opens in your default app</strong> means the system&#39;s default is used.</li><li>A vermilion dot means <strong>Your choice</strong>.</li></ul><p>You can change this later, per story, in <strong>Settings</strong>, <strong>Sources</strong>. Press <strong>Open the Library</strong>. Leathercase now writes <code>Suite.md</code> and the <code>suite/</code> folders, declares the ticked stories and opens the <a href="/guide/guide/homes-and-stories#the-library">Library</a>.</p><h3 id="step-2-first-story-i-m-starting-out" tabindex="-1">Step 2: First story (I&#39;m starting out) <a class="header-anchor" href="#step-2-first-story-i-m-starting-out" aria-label="Permalink to &quot;Step 2: First story (I&#39;m starting out)&quot;">​</a></h3><p><strong>Name the story.</strong> Type a <strong>Working title</strong> (the field suggests <em>The Salt Road</em>) and press <strong>Start the story</strong>. Leathercase makes the home&#39;s files and a folder named for the story inside your home, and opens the story on its <a href="/guide/guide/plot-grid">Plot grid</a>. Write the prose in any app you like; Leathercase reads what lands in that folder.</p><p>You don&#39;t have to start a story when the folder already holds one. If it is already a writing home, from another computer or an earlier install, the step says so, and <strong>Skip and open the home</strong> opens it as it is. If it is not a home yet but Leathercase found stories in it, <strong>Read the stories found</strong> goes on to the <strong>Stories</strong> step instead, as if you had chosen <strong>Read my manuscript</strong>.</p><p><strong>Back</strong>, at the foot of every step, returns to the step before.</p><h2 id="the-sample-library" tabindex="-1">The sample library <a class="header-anchor" href="#the-sample-library" aria-label="Permalink to &quot;The sample library&quot;">​</a></h2><p><strong>Try the sample story first</strong> opens a library Leathercase carries inside the app. It is a copy, made fresh in the app&#39;s own data folder, never in a folder of yours, so you can change anything in it and lose nothing.</p><p>It holds four short stories, one in each format Leathercase reads:</p><table tabindex="0"><thead><tr><th>Story</th><th>Format</th><th>What it shows</th></tr></thead><tbody><tr><td>The Lamp at Ferrol</td><td>Markdown</td><td>A mini novel in ten chapters: typed notes for the cast, places, items, factions and events, a hand-written threads note (<code>Story threads.md</code>, the older name, read until Leathercase&#39;s own <code>suite/StoryThreads.md</code> exists), an older <code>Outline.md</code> whose planned scene the plot grid carries into its own file, <code>suite/PlotGrid.md</code>, and work notes left out. Every view has something to show.</td></tr><tr><td>The Salt Road</td><td>Word</td><td>A novella in four <code>.docx</code> chapters, each scene a Heading 1, with folders of character and place notes.</td></tr><tr><td>Orchard Hours</td><td>Scrivener</td><td>A Scrivener 3 project with three chapter folders and a discarded scene Leathercase leaves out.</td></tr><tr><td>The Night Sleeper</td><td>Fountain</td><td>A short film in one <code>.fountain</code> screenplay.</td></tr></tbody></table><p>The sample also has six cards on the <a href="/guide/guide/writer-board">Writer Board</a> and three described tags in <a href="/guide/guide/tags">Tags</a>.</p><p><img src="'+l+'" alt="The Library of the sample, with Start here beside it" width="1130" height="852" loading="lazy"></p><h3 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h3><p>While the sample is open, a column called <strong>Start here</strong> sits beside the Library. A dashed note at its top reminds you that this is the sample and none of it is yours. Below it are six things to do once, each ticked by doing it, never by a checkbox:</p><ol><li><strong>Plot grid</strong></li><li><strong>Manuscript</strong></li><li><strong>Threads</strong></li><li><strong>Find a story, a view or a command</strong></li><li><strong>Beat board</strong></li><li><strong>Declare a story</strong></li></ol><p>The count at the top reads <strong>0 of 6</strong>, then <strong>1 of 6</strong> and so on. The next step to do has a <strong>Show me</strong> button that runs it for you. Under each step is its key, when it has one.</p><p><strong>Hide</strong> puts Start here away. It stays in the find field: click the field in the title bar with nothing typed and pick <strong>Start here</strong> to bring it back.</p><h3 id="start-over-and-leave-the-sample" tabindex="-1">Start over and Leave the sample <a class="header-anchor" href="#start-over-and-leave-the-sample" aria-label="Permalink to &quot;Start over and Leave the sample&quot;">​</a></h3><p>At the foot of Start here, and in the home switcher at the top of the sidebar while the sample is open:</p><ul><li><strong>Start over</strong> (<strong>Start the sample over</strong> in the switcher) throws the copy away and opens a fresh one, every change undone.</li><li><strong>Leave the sample</strong> forgets the sample&#39;s home and deletes its copy, with nothing left behind. If it was your only home, first run comes back so you can choose your own folder.</li></ul>',29)),r(o,{name:"getting-started-start-here",caption:"Start here ticks a step when Show me runs it, then hides and comes back from the find field"}),e[2]||(e[2]=t('<h2 id="your-first-ten-minutes" tabindex="-1">Your first ten minutes <a class="header-anchor" href="#your-first-ten-minutes" aria-label="Permalink to &quot;Your first ten minutes&quot;">​</a></h2><p>A walk through The Lamp at Ferrol, from the sample&#39;s Library. Each step names the page of this guide that covers it in full. Keys are written for Windows and Linux; on macOS use Cmd in place of Ctrl.</p><ol><li><strong>Open the story.</strong> In the Library, click <strong>The Lamp at Ferrol</strong>. The story opens on its Manuscript, and in the sidebar it expands into its views. The title bar shows when the story was read and from how many files. See <a href="/guide/guide/tour">A tour of the window</a>.</li><li><strong>Read the manuscript.</strong> Scroll through Act I. The chapters are joined into one book, and the breadcrumb follows the part and chapter at the top of the page. Pick a lens from the footer, such as the rhythm of sentence lengths. See <a href="/guide/guide/manuscript">Manuscript</a> and <a href="/guide/guide/lenses">Lenses and style checks</a>.</li><li><strong>Open the plot grid</strong> with <code>Ctrl+4</code>. Each row is a scene, read from the <code>#</code> headings of the chapters; the columns show who is in it, the point of view, the time and the threads. A row with no prose is a scene planned and not yet written. See <a href="/guide/guide/plot-grid">Plot grid</a>.</li><li><strong>Open the threads</strong> with <code>Ctrl+5</code>. The arc of Nora Vidal, the theme <em>What do we owe the drowned?</em> and the subplots run across the scenes as lanes. See <a href="/guide/guide/threads">Threads</a>.</li><li><strong>Open the Graph</strong> with <code>Ctrl+6</code>. Every name of the story is there, in groups found from the ties. Point at Nora Vidal to read her card, then drag from the ring around her name to another to tie them. See <a href="/guide/guide/graph">Graph</a>.</li><li><strong>Look at a character.</strong> Choose <strong>Characters</strong> in the sidebar, then <strong>Nora Vidal</strong>: her voice, the scenes she is in, and her sections. See <a href="/guide/guide/characters">Characters</a>.</li><li><strong>Try the beat board</strong> with <code>Ctrl+9</code>: four beat cards the sample already holds, in the columns of a structure template. See <a href="/guide/guide/beat-board">Beat board</a>.</li><li><strong>Find anything</strong> with <code>Ctrl+K</code>. Type <code>ledger</code> and see the item, the scene and the card that match. Type <code>character: Marta</code> and the last row offers to make a note for her. Press Esc to close. See <a href="/guide/guide/find">Find, open and make</a>.</li><li><strong>See how the story is read.</strong> Open the breadcrumb&#39;s view menu (the view&#39;s name with a small arrow) and choose <strong>How this story is read</strong>. It lists what Leathercase took as the cast, as prose and as left out, and why. See <a href="/guide/guide/how-a-story-is-read">How a story is read</a>.</li><li><strong>Go back to the home.</strong> Press <code>Ctrl+2</code> for the <a href="/guide/guide/desk">Desk</a>, what changed across all four stories today, then <code>Ctrl+3</code> for the <a href="/guide/guide/writer-board">Writer Board</a>, where the sample&#39;s six cards sit.</li></ol><p>When you are done, choose <strong>Leave the sample</strong> and point Leathercase at your own folder, or keep the sample as a second home beside yours.</p><h2 id="turning-things-off" tabindex="-1">Turning things off <a class="header-anchor" href="#turning-things-off" aria-label="Permalink to &quot;Turning things off&quot;">​</a></h2><p>Leathercase does little by itself, and most of what it does can be switched off. Each of these is a preference of this computer, kept in the app&#39;s own data and never in your writing home.</p><table tabindex="0"><thead><tr><th>What</th><th>Default</th><th>Where to change it</th></tr></thead><tbody><tr><td>Checking for a newer version</td><td>Off. Leathercase goes online only when you press <strong>Check now</strong>.</td><td><strong>Settings</strong>, <strong>Updates</strong>, <strong>Check when Leathercase opens</strong></td></tr><tr><td>Keys that work from any app (<strong>Capture to Writer</strong>, <strong>Show Leathercase</strong>)</td><td>Off</td><td><strong>Settings</strong>, <strong>Hotkeys</strong>, <strong>Turn on global keys</strong></td></tr><tr><td>The mate&#39;s heartbeat: looking at a story after a save and every half hour</td><td>On. It reads on this computer and wakes no model.</td><td><strong>Settings</strong>, <strong>The mate</strong>, <strong>Heartbeat</strong></td></tr><tr><td>The mate&#39;s next steps: one suggestion at a time from commands not tried yet</td><td>On</td><td><strong>Settings</strong>, <strong>The mate</strong>, <strong>Next steps</strong></td></tr><tr><td>The mate&#39;s notifications</td><td>In the app only, never a sound</td><td><strong>Settings</strong>, <strong>The mate</strong>, <strong>Notifications</strong></td></tr><tr><td>Waking a model</td><td>Off, and the app offers no model yet</td><td><strong>Settings</strong>, <strong>The mate</strong>, <strong>When it may wake a model</strong></td></tr><tr><td>The assistant&#39;s layer: what agents proposed, drawn over the views</td><td>On</td><td><code>Ctrl+.</code>, or <strong>Show or hide the assistant&#39;s layer</strong> in the View menu</td></tr><tr><td>Style checks tinted by the style lens</td><td>All eight kinds on</td><td><strong>Settings</strong>, <strong>Lenses</strong>, <strong>Style checks</strong></td></tr><tr><td>Fades</td><td>On</td><td><strong>Settings</strong>, <strong>Accessibility</strong>, <strong>Reduce motion</strong></td></tr><tr><td>The window&#39;s size</td><td>100%</td><td><code>Ctrl+=</code> and <code>Ctrl+-</code>, or <strong>Settings</strong>, <strong>Accessibility</strong>, <strong>Zoom</strong></td></tr><tr><td>Start here on the sample</td><td>Shown</td><td><strong>Hide</strong> at its foot</td></tr></tbody></table><p>Lenses on the manuscript are never on until you pick one, and only one shows at a time. For every setting, see <a href="/guide/reference/settings">Settings</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/tour">A tour of the window</a></li><li><a href="/guide/guide/homes-and-stories">Homes and stories</a></li><li><a href="/guide/guide/declare-a-story">Declaring a story</a></li><li><a href="/guide/reference/updates">Updates and uninstalling</a></li><li><a href="/guide/reference/privacy">Privacy</a></li></ul>',10))])}const k=a(g,[["render",c]]);export{b as __pageData,k as default};
